"""Actual Stories Header volume root + inherited button input, real rpl.

Qt/focus/timers/fade/paint/controller are mechanical doubles; no native UI/profile.
Normal FadeWrap target visibility is not effective child focusability.
"""
from pathlib import Path
from library_regressions import cpp, function, source


def check(root):
    text = source('Telegram/SourceFiles/media/stories/media_stories_header.cpp')
    button = source('Telegram/lib_ui/ui/abstract_button.cpp')
    local = function(text, 'class VolumeToggle final') + ';' if 'class VolumeToggle final' in text else ''
    helper = function(text, 'void MakeVolumeControlFocusable(') if 'void MakeVolumeControlFocusable(' in text else ''
    methods = '\n'.join(function(text, sig) for sig in (
        'void Header::createVolumeToggle(', 'void Header::rebuildVolumeControls(', 'void Header::updateVolumeIcon('))
    tooltip = function(text, 'void Header::toggleTooltip(')
    # Execute real ownership/hide/announcement routing; tooltip copy/layout are doubled.
    tooltip_routing = tooltip[:tooltip.index('\n\tconst auto text =')].replace(
        '\tconst auto guard', '\t++tooltipCalls;\n\tconst auto guard', 1) + r'''
    _tooltipType = type;
    _tooltip = std::make_unique<ImportantTooltip>();
}
'''
